export interface InsuredItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: InsuredItem[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

const PROCESSING_FEE = 5;
const SWORD_BASE_PREMIUM = 100;
const PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

function quote(step: QuoteStep): QuoteResult {
  const policyBasePremium = step.items.length * SWORD_BASE_PREMIUM;
  // Kept in hundredths of a G so the percentage stays exact until final rounding.
  const premiumInHundredths =
    policyBasePremium * (PERCENT + FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE * PERCENT;
  return { premium: Math.ceil(premiumInHundredths / PERCENT) };
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: scenario.steps.map(quote) };
}
